import time

def process_with_retry(msg, handler, dlq, max_attempts=5):
    for attempt in range(max_attempts):
        try:
            handler(msg)
            return
        except TransientError:
            backoff = min(2 ** attempt, 60)
            time.sleep(backoff)  # exponential backoff, capped
        except PoisonError:
            dlq.send(msg, reason="invalid payload")
            return
    # Exhausted retries: treat as poison
    dlq.send(msg, reason="max attempts exceeded")
